INCLUDE_ASM("fe/feasyncfile", cFEAsyncManager_LoadDataFile);
#ifdef SKIP_ASM
struct sFEAsyncFile {
    char name[0x100];
    void* data;    // 0x100
    int handle;    // 0x104
    int async;     // 0x108
    int size;      // 0x10C
    int pad110;
    int status;    // 0x114
    int pad118;
};

struct sFEAsyncFiles {
    sFEAsyncFile files[5];
};

extern char str_FE_Async_Texture[];
// PORT: operator_new__FUi really takes (size, tag, flags, d)
void* operator_new_tag(unsigned int size, const char* tag, int flags, int d) __asm__("operator_new__FUi");
extern "C" int ASYNCFILE_loadat(void* file, void* data, int size);
extern "C" void FILE_loadatz(void* file, void* data, int size);

/**
 * Starts reading a slot's file into a new buffer of a fixed 0x109A0 bytes (tag "FE Async Texture").
 *
 * Sets the status to 2 (loading). With the slot's async flag it starts an asynchronous read
 * (ASYNCFILE_loadat) and keeps its handle; otherwise it reads synchronously (FILE_loadatz) and sets
 * status 3 directly, skipping the texture step that cFEAsyncManager_Update() runs only for asynchronous
 * loads.
 *
 * @param idx  index of the file slot (On Tour fileNum)
 */
void cFEAsyncManager::LoadDataFile(int idx)
{
    sFEAsyncFiles* asyncMan = (sFEAsyncFiles*)this;
    void** pData;
    void** dataField;
    asyncMan->files[idx].size = 0x109A0;
    // &files[idx].data, spelled as slot 0's field plus idx slots: retail adds the 0x100 before the slot offset.
    dataField = &asyncMan->files[0].data;
    pData = dataField + idx * (sizeof(sFEAsyncFile) / sizeof(void*));
    *pData = operator_new_tag(0x109A0, str_FE_Async_Texture, 0x25000000, 0);
    SetFileStatus(idx, kFileLoading);
    if (asyncMan->files[idx].async != 0) {
        SetFileStatus(idx, kFileLoading);
        asyncMan->files[idx].handle = ASYNCFILE_loadat(&asyncMan->files[idx], *pData, asyncMan->files[idx].size);
    } else {
        FILE_loadatz(&asyncMan->files[idx], *pData, asyncMan->files[idx].size);
        SetFileStatus(idx, kFileLoaded);
    }
}
#endif

