/**
 * Moves the buddy list's scroll thumb to show position @p pos of @p count entries.
 *
 * Needs mpScreen and 0 <= pos <= count, count > 0. Reads the track "ScrollVector" (its size through vtable entry 20,
 * getSize) and places "ScrollButton" at the track's mPosition plus x -2 and y pos * (height - 15) / (count - 1
 * when count >= 2), then makes both visible.
 *
 * @param pos  selected index
 * @param count  number of entries
 */
void cFEStateNetMessenger::placeScrollThumb(int pos, int count)
{
    if (mpScreen == 0) return;
    if (pos < 0) return;
    if (count < pos) return;
    if (count <= 0) return;
    cUIThing* track = cUIScreen_getObjectByHashName(mpScreen, GetHashValue32(str_ScrollVector));
    cUIThing* thumb = cUIScreen_getObjectByHashName(mpScreen, GetHashValue32(str_ScrollButton));
    if (thumb == 0) return;
    if (track == 0) return;
    t3Vector size;
    track->getSize(&size);
    t3Vector trackPos = track->mPosition;
    float fpos = (float)pos;
    if (count >= 2) count--;
    float step = (size.y + -15.0f) / (float)count;
    t3Vector np = trackPos;
    np.y += fpos * step;
    np.x += -2.0f;
    thumb->mPosition = np;
    thumb->setVisible(1);
    track->setVisible(1);
}
#endif

