/**
 * Trims a text scroller and restores its scroll position after it was refilled.
 *
 * With @p trim it deletes lines from the top until @p keep remain. It then scrolls to the end when the previous
 * position was the last line (total == pos + 1) or @p scrollToEnd is set (sel = count - @p sel, top = last line), to
 * the top when pos was 0, else back to the old pos/selIndex minus the removed lines.
 *
 * @param list  the cUITextScroll
 * @param keep  lines to keep
 * @param sel  visible line count
 * @param total  line count before the refill
 * @param pos  top line before the refill
 * @param selIndex  selected line before the refill
 * @param scrollToEnd  non-zero to jump to the end
 * @param trim  non-zero to delete surplus lines
 */
extern "C" void trimAndRestoreTextScroll(cUITextScroll* list, int keep, unsigned int sel, int total, int pos, int selIndex, int scrollToEnd, int trim)
{
    if (list == 0) return;
    int toEnd = 0;
    if (total == pos + 1 || scrollToEnd != 0) toEnd = 1;
    int n = list->mLineSize - keep;
    int atStart = pos == 0;
    int removed = 0;
    if (n > 0 && trim != 0) {
        for (removed = 0; removed < n; removed++) {
            cUITextScroll_deleteLineByIndex(list, 0);
        }
    }
    if (toEnd) {
        unsigned short lineCount = list->mLineSize;
        if (sel >= lineCount) {
            list->mLinesOffset = 0;
        } else {
            list->mLinesOffset = lineCount - sel;
        }
        list->mSelectedIndex = list->mLineSize - 1;
    } else if (atStart) {
        list->mLinesOffset = 0;
        list->mSelectedIndex = 0;
    } else {
        int newTop = pos - removed;
        if (newTop <= 0) {
            list->mSelectedIndex = 0;
            list->mLinesOffset = 0;
        } else {
            int newSel = selIndex - removed;
            if (newSel <= 0) {
                list->mLinesOffset = 0;
            } else {
                list->mLinesOffset = newSel;
            }
            list->mSelectedIndex = newTop;
        }
    }
}
