#ifdef SKIP_ASM
extern "C" int strlen(const char* s);


/**
 * Fills mszMaskedText with one '*' per character of @p str (at most 63), or " " for an empty string.
 *
 * Likely bug: for strings longer than 63 characters the terminator is written at index strlen(str), past the 0x40-byte
 * buffer.
 *
 * @param str  the password to mask
 */
void cFEStateNet::setMaskedText(const char* str)
{
    cFEStateNet* feStateNet = this;
    int len = strlen(str);
    int i;
    for (i = 0; i < len && i < 0x3F; i++) {
        feStateNet->mszMaskedText[i] = '*';
    }
    if (len == 0) {
        feStateNet->mszMaskedText[0] = ' ';
        len = 1;
    }
    feStateNet->mszMaskedText[len] = 0;
}
#endif

