/**
 * Polls BuddyMan for messages and challenges at most once a second (cFEStateNet's vtable entry 27).
 *
 * Only with a screen and when vtable entry 29 is non-zero. When 1..59 frames have passed since mLastPollFrame it
 * returns; otherwise it stores the frame, starts or stops mMessageHintFrame from the message count (BuddyMan_getNumMessages) and
 * mChallengeHintFrame from the challenger list, and shows the count in "TextMessageCount" (" " and hidden when there
 * are none).
 */
void cFEStateNet::pollPendingMessages()
{
    char buf[16];
    if (mpScreen == 0) {
        return;
    }
    if (((cFEVObj_001AAB68*)this)->showsOnline() == 0) {
        return;
    }
    unsigned int now = (unsigned int)cAppMan_TheAppMan->TimerTick;
    unsigned int elapsed = now - mLastPollFrame;
    if (elapsed > 0 && elapsed < 60) {
        return;
    }
    mLastPollFrame = now;
    int n = BuddyMan_getNumMessages(GetSession_001AAB68());
    if (mMessageHintFrame != 0) {
        if (n <= 0) {
            mMessageHintFrame = 0;
        }
    } else {
        if (n > 0) {
            mMessageHintFrame = now;
        }
    }
    int has = Count1AAB68((BuddyMan*)GetSession_001AAB68()) != 0;
    if (mChallengeHintFrame != 0) {
        if (!has) {
            mChallengeHintFrame = 0;
        }
    } else {
        if (has) {
            mChallengeHintFrame = now;
        }
    }
    cFEVObj_001AAB68* text = (cFEVObj_001AAB68*)cUIScreen_getObjectByHashName(mpScreen, GetHashValue32(str_TextMessageCount));
    if (text == 0) {
        return;
    }
    if (n > 0) {
        text->setVisible(1);
        sprintf(buf, str_pct_d_b, n);
        cUIText_setAsciiString((cUIText*)text, buf);
    } else {
        text->setVisible(0);
        cUIText_setAsciiString((cUIText*)text, str_sp);
    }
}
