/**
 * Returns the localised text for a network-connection error code (a '-xxx' code at @p msg +0x8).
 *
 * '-dif' DifferentPS2, '-dev' Locate, '-cfg' NetConfig, '-ini' HardwareInit, '-ton' Dialtone, '-bsy' Busy, '-con'
 * Connect, '-ath' PPP, and '-???', '-dns', 'time' ISPFail (kT_POPUP200*), looked up through SSXApp->FELocale's vtable
 * entry 4.
 *
 * @param msg  the error event
 * @return the unicode text, or 0 for an unknown code
 */
int cFEStateNet::getNetErrorText(online_NetErrorEvent* msg)
{
    int textId;
    switch ((unsigned int)msg->mError) {
    case kNetErr_dif:
        textId = GetHashValue32(str_kT_POPUP200DifferentPS2);
        break;
    case kNetErr_dev:
        textId = GetHashValue32(str_kT_POPUP200Locate);
        break;
    case kNetErr_cfg:
        textId = GetHashValue32(str_kT_POPUP200NetConfig);
        break;
    case kNetErr_ini:
        textId = GetHashValue32(str_kT_POPUP200HardwareInit);
        break;
    case kNetErr_ton:
        textId = GetHashValue32(str_kT_POPUP200Dialtone);
        break;
    case kNetErr_bsy:
        textId = GetHashValue32(str_kT_POPUP200Busy);
        break;
    case kNetErr_con:
        textId = GetHashValue32(str_kT_POPUP200Connect);
        break;
    case kNetErr_unknown:
        textId = GetHashValue32(str_kT_POPUP200ISPFail);
        break;
    case kNetErr_ath:
        textId = GetHashValue32(str_kT_POPUP200PPP);
        break;
    case kNetErr_dns:
        textId = GetHashValue32(str_kT_POPUP200ISPFail);
        break;
    case kLobbyErr_time:
        textId = GetHashValue32(str_kT_POPUP200ISPFail);
        break;
    default:
        return 0;
    }
    return ((cLocStr_001AAF90*)SSXApp->FELocale)->getStringByHash(textId);
}
