/**
 * Fills the received-challenge screen's option texts from the race setup.
 *
 * Each is " " when @p iface is null. "TextEventResult" cBENewRaceInterface_getEventName, "TextCourseResult" cBENewRaceInterface_getLocationName1,
 * "TextRankedGameResult" Yes/No from cBENetworkInterface_networkOpt.bIsRankedGame; "TextPowerupsResult", "TextMultipliersResult" and
 * "TextPointiconsResult" show "kT_CMNNo" when bit 8, 6 or 7 of D_005308D0 is set, else "kT_CMNYes";
 * "TextCPURidersResult" shows the AI count (newRace.iNumberAI) or "kT_CMNHUDNone" when it is 0 or less.
 *
 * @param iface  the new-race interface (only tested for null)
 * @param screen  the screen (null: nothing)
 */
void cFEStateChallengeReceivedPopup::fillRaceTexts(void* iface, cUIScreen* screen)
{
    char buf[16];
    if (((void*)screen) == 0) {
        return;
    }
    cUIText* uiText = cUIScreen_getObjectByHashName(screen, GetHashValue32(str_TextEventResult));
    if (uiText != 0) {
        if (iface == 0) {
            cUIText_setAsciiString(uiText, str_sp);
        } else {
            cUIText_setAsciiString(uiText, cBENewRaceInterface_getEventName(iface));
        }
    }
    uiText = cUIScreen_getObjectByHashName(screen, GetHashValue32(str_TextCourseResult));
    if (uiText != 0) {
        if (iface == 0) {
            cUIText_setAsciiString(uiText, str_sp);
        } else {
            cUIText_setAsciiString(uiText, cBENewRaceInterface_getLocationName1(iface));
        }
    }
    uiText = cUIScreen_getObjectByHashName(screen, GetHashValue32(str_TextRankedGameResult));
    if (uiText != 0) {
        if (iface == 0) {
            cUIText_setAsciiString(uiText, str_sp);
        } else {
            cBE_getInterface_Fv(SSXApp->BE, 7);
            if (cBENetworkInterface_networkOpt.bIsRankedGame != 0) {
                cUIText_setUnicodeStringByID(uiText, GetHashValue32(str_kT_CMNYes));
            } else {
                cUIText_setUnicodeStringByID(uiText, GetHashValue32(str_kT_CMNNo));
            }
        }
    }
    uiText = cUIScreen_getObjectByHashName(screen, GetHashValue32(str_TextPowerupsResult));
    if (uiText != 0) {
        if (iface == 0) {
            cUIText_setAsciiString(uiText, str_sp);
        } else {
            if ((D_005308D0[0] >> 8) & 1) {
                cUIText_setUnicodeStringByID(uiText, GetHashValue32(str_kT_CMNNo));
            } else {
                cUIText_setUnicodeStringByID(uiText, GetHashValue32(str_kT_CMNYes));
            }
        }
    }
    uiText = cUIScreen_getObjectByHashName(screen, GetHashValue32(str_TextMultipliersResult));
    if (uiText != 0) {
        if (iface == 0) {
            cUIText_setAsciiString(uiText, str_sp);
        } else {
            if ((D_005308D0[0] >> 6) & 1) {
                cUIText_setUnicodeStringByID(uiText, GetHashValue32(str_kT_CMNNo));
            } else {
                cUIText_setUnicodeStringByID(uiText, GetHashValue32(str_kT_CMNYes));
            }
        }
    }
    uiText = cUIScreen_getObjectByHashName(screen, GetHashValue32(str_TextPointiconsResult));
    if (uiText != 0) {
        if (iface == 0) {
            cUIText_setAsciiString(uiText, str_sp);
        } else {
            int pointIconsBits = D_005308D0[0] >> 7;
            if (pointIconsBits & 1) {
                cUIText_setUnicodeStringByID(uiText, GetHashValue32(str_kT_CMNNo));
            } else {
                cUIText_setUnicodeStringByID(uiText, GetHashValue32(str_kT_CMNYes));
            }
        }
    }
    uiText = cUIScreen_getObjectByHashName(screen, GetHashValue32(str_TextCPURidersResult));
    if (uiText != 0) {
        if (iface == 0) {
            cUIText_setAsciiString(uiText, str_sp);
        } else {
            cBE_getInterface_Fv(cBE_getBE(), 0);
            int n = cBENewRaceInterface_newRace.iNumberAI;
            if (n <= 0) {
                cUIText_setUnicodeStringByID(uiText, GetHashValue32(str_kT_CMNHUDNone));
            } else {
                sprintf(buf, str_pct_d_b, n);
                cUIText_setAsciiString(uiText, buf);
            }
        }
    }
}
#endif

