static inline int IsHash_001B10F8(int id, char* name) { return id == GetHashValue32(name); }

/**
 * Sets up the rider-select widgets as the screen creates them.
 *
 * "LBChallengerSelect" loses attribute bit 0, gets the ten riders' names (cBECharacterInterface_getShortNameByCharacter on the character interface
 * for each id in cFEStateCharSelect_characterOrder), becomes visible, is preset to the player's current rider (stored in miCharID) and is
 * kept in mpLBChallengerSelect (then slot 24 with 1). "TextOpponentSelect" gets the str_sp text and colour (1, 0,
 * 0, 0).
 *
 * @param pWidget  the widget being created (On Tour pWidget)
 */
void cFEStateOnlineCharacterSelect::onWidgetCreate(cUIThing* pWidget)
{
    cUIText* text = (cUIText*)pWidget;
    cFEVObj_001B10F8* box = (cFEVObj_001B10F8*)text;
    if (IsHash_001B10F8(text->mHashName, str_LBChallengerSelect)) {
        text->mAttr &= ~1;
        int i;
        for (i = 0; i < 10; i++) {
            cUIListBox_addEntryByAsciiString(text, (const char*)cBECharacterInterface_getShortNameByCharacter(cBE_getInterface_Fv(cBE_getBE(), 2), cFEStateCharSelect_characterOrder[i], 0), cFEStateCharSelect_characterOrder[i]);
        }
        text->mAttr &= ~1;
        box->setVisible(1);
        int id = cBENewPlayerInterface_getPlayerCharID(cBE_getInterface_Fv(SSXApp->BE, 1), 0);
        miCharID = id;
        cUIListBox_setCurrentEntryByIndex(text, (unsigned char)findOnlineCharacterRow(id));
        mpLBChallengerSelect = (cUIListBox*)text;
        box->setUseStaticColour(1);
    } else if (IsHash_001B10F8(text->mHashName, str_TextOpponentSelect)) {
        cUIText_setAsciiString(text, str_sp);
        box->setColour(sVec4_001B10F8(1.0f, 0.0f, 0.0f, 0.0f));
    }
}
#endif

