/**
 * Builds a room's display name: its localised skill level for a known prefix, then the rest of the name.
 *
 * Splits @p src at the first '.' (at most 127 characters before it). A prefix of "Elite", "Advanced", "Intermediate" or
 * "Beginner" becomes "kT_POPUP232Elite", "Advanced", "Voice" (for "Intermediate") or "Beginner"; any other prefix is
 * copied as is. Then " " plus the text after the dot is appended. A null @p src leaves @p out untouched.
 *
 * @param src  the room name ("Prefix.rest")
 * @param out  16-bit-character output buffer
 */
extern "C" void buildRoomDisplayName(const char* src, void* out)
{
    char name[128];
    char ext[128];
    unsigned short wext[128];
    if (src == 0) {
        return;
    }
    int i;
    for (i = 0; src[i] != '.' && i < 127; i++) {
        name[i] = src[i];
    }
    name[i] = 0;
    i++;
    ext[0] = ' ';
    int j;
    for (j = 1; src[i] != 0 && j < 128; i++, j++) {
        ext[j] = src[i];
    }
    ext[j] = 0;
    if (strcmp(name, cFEStateLobbyMenu_eliteChannelName) == 0) {
        strcpy1(out, Loc1B25E0(str_kT_POPUP232Elite));
    } else if (strcmp(name, cFEStateLobbyMenu_advancedChannelName) == 0) {
        strcpy1(out, Loc1B25E0(str_kT_POPUP232Advanced));
    } else if (strcmp(name, cFEStateLobbyMenu_intermediateChannelName) == 0) {
        strcpy1(out, Loc1B25E0(str_kT_POPUP232Voice));
    } else if (strcmp(name, cFEStateLobbyMenu_beginnerChannelName) == 0) {
        strcpy1(out, Loc1B25E0(str_kT_POPUP232Beginner));
    } else {
        strcpy3(out, name);
    }
    UIAsciiToUnicode(wext, ext);
    strcat1(out, wext);
}
