// the 'netw'/'list' reply buffer filled by cCommSystem_netConnQuery (10 entries of 0x100 bytes, count in cCommSystem_mNumNetConn)
struct sNetEntry_4CD8 { int f0; char name4[0x3E]; char name42[0xBE]; };
extern sNetEntry_4CD8 cCommSystem_mNetConns[10];



/**
 * Loads the network configurations from the memory card in the current slot and lists them.
 *
 * Reads "mc0:" or "mc1:" (D_004A1B90[cFEStateNetConfig_cardDevice]) with cCommSystem_netConnQuery into cCommSystem_mNetConns; miNumSettings is the
 * count, at most 4. None or an error on slot 1: tries slot 2 ("checking" popup, miState 1, miResult = the count). On
 * slot 2 an error goes to cFEStateNetConfig_reportLoadResult (miState 0), or, when slot 1 found none (miResult 0), the slot is reset to 0.
 * With configurations each one gets a row in mpLBSettings ("%d: " plus its name fitted to the box width when there are
 * 2 or more; data 20 + i) and its device name in mpLBAdapters (data 30 + i; both branches of the "SCE/Ethernet (Network
 * Adaptor)" test add it the same way), then cFEStateNetConfig_showConfigLists shows the lists. Ends in miState 5 with miWaitFrames 15.
 */
void cFEStateNetConfig::loadConfigs()
{
    char buf[64];
    unsigned short name[64];
    unsigned short line[64];
    tRect size;
    t3Vector scale;
    tRect pos;
    cCommSystem_netConnQuery(cCommSystem_mCommSystem, D_004A1B90[cFEStateNetConfig_cardDevice]);
    miNumSettings = cCommSystem_mNumNetConn;
    if (miNumSettings > 4) {
        miNumSettings = 4;
    }
    if (miNumSettings <= 0) {
        if (cFEStateNetConfig_cardDevice == 0) {
            cFEStateNetConfig_cardDevice = 1;
            this->showCheckingCardPopup(2);
            miState = 1;
            miResult = miNumSettings;
            return;
        }
        if (miNumSettings != 0) {
            if (miResult == 0) {
                cFEStateNetConfig_cardDevice = 0;
                miState = 5;
                miWaitFrames = 15;
                return;
            }
            reportLoadResult(miNumSettings);
            miState = 0;
            return;
        }
    } else {
        ((cUIThing*)cUIScreen_getObjectByHashName(mpScreen,
                GetHashValue32(str_LBSettings)))->getSize((t3Vector*)&pos);
        scale = *(&mpLBSettings->mScale);
        if (miNumSettings > 4) {
            miNumSettings = 4;
        }
        for (int i = 0; i < miNumSettings; i++) {
            char* nm = cCommSystem_mNetConns[i].name42;
            float w;
            int len;
            if (miNumSettings >= 2) {
                len = sprintf(buf, str_pct_d_c, i + 1);
                w = pos.X - cFont_textExtent(cUIListBox_getFont(mpLBSettings), buf, &size, 1, scale.x, scale.y);
            } else {
                w = pos.X;
                len = 0;
                buf[0] = 0;
            }
            char* rec = cCommSystem_mNetConns[i].name4;
            _Utf8DecodeStringToUCS2(name, 0x40, nm);
            UIAsciiToUnicode(line, buf);
            cFont_textSmartLimit1(cUIListBox_getFont(mpLBSettings), scale.x, w, name, line + len, 0x40 - len);
            cUIListBox_addEntryByUnicodeString(mpLBSettings, line, i + 20);
            if (strcmp(D_004A1B7C, rec) == 0) {
                cUIListBox_addEntryByAsciiString(mpLBAdapters, rec, i + 0x1E);
            } else {
                cUIListBox_addEntryByAsciiString(mpLBAdapters, rec, i + 0x1E);
            }
        }
        showConfigLists(miNumSettings);
    }
    miState = 5;
    miWaitFrames = 15;
}
#endif

