INCLUDE_ASM("fe/feasyncfile", cFEStateNetAccountMem_showPopup);
#ifdef SKIP_ASM
extern "C" void* cFEStateNet_createPopup(cFEStateNet* self);
extern "C" void cFEStateNet_showPopup(cFEStateNet* self, cScreenPopup* popup);
void cPopupInfo_setPopupOptionNames2(void* self, int a1, int a2);

/**
 * Shows a popup for the account memory-card popup: 0, 1 or 2 buttons, optional title and unicode body text.
 *
 * Two buttons get @p defaultSel as miDefaultOption, one button option 0; with none it is button-less. The title and
 * body are stored as unicode string pointers (type 1). Sets miMiscData to @p popupId, mbPassUpdate, and clears
 * mbReceivePrev (no back) in every case.
 *
 * @param popupId  popup id (the step to go to on Yes)
 * @param defaultSel  default option with two buttons
 * @param firstButton  hash of the first option text, or 0 for none
 * @param secondButton  hash of the second option text, or 0
 * @param titleText  unicode title, or 0
 * @param bodyText  unicode message, or 0
 */
extern "C" void cFEStateNetAccountMem_showPopup(cFEStateNetAccountMem* self, int popupId, int defaultSel, int firstButton,
        int secondButton,
    const unsigned short* titleText, const unsigned short* bodyText)
{
    cScreenPopup* popup = (cScreenPopup*)self->createPopup();
    cPopupInfo* sub = &popup->info;
    if (firstButton != 0) {
        if (secondButton != 0) {
            popup->info.meType = 2;
            sub->setPopupOptionNames2(0, firstButton);
            sub->setPopupOptionNames2(1, secondButton);
            popup->info.miDefaultOption = defaultSel;
        } else {
            popup->info.meType = 1;
            sub->setPopupOptionNames2(0, firstButton);
            popup->info.miDefaultOption = 0;
        }
    } else {
        popup->info.meType = 0;
        popup->info.mbReceivePrev = 0;
        popup->info.miDefaultOption = 0;
    }
    if (titleText != 0) {
        sub->mtTitle.pustr = titleText;
        sub->mtTitle.eType = 1;
    }
    if (bodyText != 0) {
        sub->mtMessage.pustr = bodyText;
        sub->mtMessage.eType = 1;
    }
    sub->miMiscData = popupId;
    sub->mbReceivePrev = 0;
    sub->mbPassUpdate = 1;
    self->showPopup(popup);
}
#endif

