/**
 * Handles the account popup's events per card state and tells the parent state the result when it closes.
 *
 * Results are reported to mpParentState's slot 17 on kONPOPUPDESTROY (closed); a result is itself a popup event (0xF
 * option 0, 0x10 option 1, 0x11 option 2). States 7/13/21/25 (card prompts): kONSCREENPOPUPOPTION0 goes to
 * cFEStateNetAccountMem_getErrorStep's follow-up step for the state when the card changed (cSharedLoginMan_isCardMissing; error 2) or mbCardError is set
 * (error 6), else to the popup's next state (+0x18) when nonzero; kONSCREENPOPUPOPTION1 / kONSCREENPOPUPPREV set
 * miResult 0x11 (in 7/13/25) or 0x10; kONPOPUPDESTROY reports miResult. State 3: OPTION0 restarts from miStartState
 * when miMiscData is set (else result 0x10), OPTION1 / PREV result 0xF. States 9/15/17/28: OPTION0 result 0x11,
 * OPTION1 / PREV result 0xF. State 23: OPTION0 restarts from step 0 when mbAccountMismatch is set, else result 0x10.
 * States 4/10/18/24/29 report 0xF on close. Every event also goes to the cFEStateNet handler
 * (cFEStateNet_onPopupEvent).
 *
 * @param w  the popup state that sent the event (On Tour pPopup); its miMiscData names the next state
 * @param msg  the popup event (On Tour Event; kONSCREENPOPUPOPTION0 + i option i, kONSCREENPOPUPPREV back,
 *             kONPOPUPDESTROY closed)
 */
void cFEStateNetAccountMem::onPopupEvent(cUIState* w, unsigned int msg)
{
    int result;
    switch (miState) {
    case 7:
    case 13:
    case 21:
    case 25:
        switch (msg) {
        case cUIState::kONSCREENPOPUPOPTION0:
            cFEStateNet_onPopupEvent_v(this, w, cUIState::kONSCREENPOPUPOPTION0);
            if (cSharedLoginMan_isCardMissing(SharedLoginMan) != 0) {
                miError = 2;
                cFEStateNetAccountMem_setStep(this, this->getErrorStep(miState));
            } else if (mbCardError != 0) {
                miError = 6;
                cFEStateNetAccountMem_setStep(this, this->getErrorStep(miState));
            } else {
                int x = w->miMiscData;
                if (x != 0) {
                    cFEStateNetAccountMem_setStep(this, x);
                }
            }
            break;
        case cUIState::kONSCREENPOPUPOPTION1:
        case cUIState::kONSCREENPOPUPPREV: {
            cFEStateNet_onPopupEvent_v(this, w, msg);
            int st = miState;
            if (st == 25 || st == 13 || st == 7) {
                miResult = cUIState::kONSCREENPOPUPOPTION2;
            } else {
                miResult = cUIState::kONSCREENPOPUPOPTION1;
            }
            break;
        }
        case cUIState::kONPOPUPDESTROY:
            cFEStateNet_onPopupEvent_v(this, w, cUIState::kONPOPUPDESTROY);
            mpParentState->onPopupEvent(this, miResult);
            break;
        default:
            cFEStateNet_onPopupEvent_v(this, w, msg);
            break;
        }
        break;
    case 3:
        switch (msg) {
        case cUIState::kONSCREENPOPUPOPTION0:
            cFEStateNet_onPopupEvent_v(this, w, cUIState::kONSCREENPOPUPOPTION0);
            if (miMiscData != 0) {
                miResult = 0;
                miError = 0;
                mbCardError = 0;
                cFEStateNetAccountMem_setStep(this, miStartState);
            } else {
                miResult = cUIState::kONSCREENPOPUPOPTION1;
            }
            break;
        case cUIState::kONSCREENPOPUPOPTION1:
        case cUIState::kONSCREENPOPUPPREV:
            cFEStateNet_onPopupEvent_v(this, w, msg);
            miResult = cUIState::kONSCREENPOPUPOPTION0;
            break;
        case cUIState::kONPOPUPDESTROY:
            cFEStateNet_onPopupEvent_v(this, w, cUIState::kONPOPUPDESTROY);
            result = miResult;
            if (result != 0) {
                mpParentState->onPopupEvent(this, result);
            }
            break;
        default:
            cFEStateNet_onPopupEvent_v(this, w, msg);
            break;
        }
        break;
    case 9:
    case 15:
    case 17:
    case 28:
        switch (msg) {
        case cUIState::kONSCREENPOPUPOPTION0:
            cFEStateNet_onPopupEvent_v(this, w, cUIState::kONSCREENPOPUPOPTION0);
            miResult = cUIState::kONSCREENPOPUPOPTION2;
            break;
        case cUIState::kONSCREENPOPUPOPTION1:
        case cUIState::kONSCREENPOPUPPREV:
            cFEStateNet_onPopupEvent_v(this, w, msg);
            miResult = cUIState::kONSCREENPOPUPOPTION0;
            break;
        case cUIState::kONPOPUPDESTROY:
            cFEStateNet_onPopupEvent_v(this, w, cUIState::kONPOPUPDESTROY);
            result = miResult;
            if (result != 0) {
                mpParentState->onPopupEvent(this, result);
            }
            break;
        default:
            cFEStateNet_onPopupEvent_v(this, w, msg);
            break;
        }
        break;
    case 23:
        switch (msg) {
        case cUIState::kONSCREENPOPUPOPTION0:
            cFEStateNet_onPopupEvent_v(this, w, cUIState::kONSCREENPOPUPOPTION0);
            if (mbAccountMismatch == 0) {
                miResult = cUIState::kONSCREENPOPUPOPTION1;
            } else {
                miResult = 0;
                miError = 0;
                mbCardError = 0;
                mbAccountMismatch = 0;
                miStartState = 0;
                cFEStateNetAccountMem_setStep(this, 0);
            }
            break;
        case cUIState::kONPOPUPDESTROY:
            cFEStateNet_onPopupEvent_v(this, w, cUIState::kONPOPUPDESTROY);
            result = miResult;
            if (result != 0) {
                mpParentState->onPopupEvent(this, result);
            }
            break;
        default:
            cFEStateNet_onPopupEvent_v(this, w, msg);
            break;
        }
        break;
    case 4:
    case 10:
    case 18:
    case 24:
    case 29:
        if (msg == cUIState::kONPOPUPDESTROY) {
            cFEStateNet_onPopupEvent_v(this, w, cUIState::kONPOPUPDESTROY);
            mpParentState->onPopupEvent(this, cUIState::kONSCREENPOPUPOPTION0);
        } else {
            cFEStateNet_onPopupEvent_v(this, w, msg);
        }
        break;
    default:
        cFEStateNet_onPopupEvent_v(this, w, msg);
        break;
    }
}
#endif

