        mpMenuPlayers = (cUIMenu*)obj;
        cUIMenu_setInputMap(obj, 1);
        mpMenuPlayers->setFocus(1);
        cUIMenu_setScrollableMenu(mpMenuPlayers, 1);
        mpMenuPlayers->mAttr &= ~0x80;
        mpMenuPlayers->mAttr |= 1;
