/**
 * Handles the create-room widgets: name and password entry, channel choice, done and back.
 *
 * kONNEXT by id: 1 opens the keyboard on the room name ("kT_POPUP231NewRoom", keyboard id 1, 8 characters), 2 on the
 * password ("kT_POPUP231AddPassword", id 2, 8 characters), 3 (done) tells the parent 0xF (slot 17) once cFEStateNetCreateRoomPopup_checkRoomName
 * accepts the form. kONPREV tells the parent kONSCREENPOPUPPREV. kONCHANGE on mpLBChannelName sets mszChannelName from
 * the entry id: 0 "Elite", 1 "Advanced", 2 "Beginner", 3 "Intermediate" (the entry labelled Voice). kONKEYBOARDEND
 * (keyboard done) stores the typed text in mszRoomName or mszPassword by the keyboard's id and shows it, then falls
 * through to the cFEStateNet handler like the other events.
 *
 * @param pWidget  the widget (On Tour pWidget)
 * @param msg  the widget event (On Tour Event)
 */
void cFEStateNetCreateRoomPopup::onWidgetEvent(cUIThing* pWidget, unsigned int msg)
{
    cUIThing* obj = pWidget;
    switch (msg) {
    case cUIState::kONNEXT:
        switch (obj->mMiscData) {
        case 1:
            this->openKeyboardWithLabelID(mpTextRoomName, GetHashValue32(str_kT_POPUP231NewRoom),
                    mszRoomName, 0, 1, 8);
            cKeyboardPopup_setIncludeKey(mpKeyboard, 53, 0, 2);
            break;
        case 2:
            this->openKeyboardWithLabelID(mpTextPassword, GetHashValue32(str_kT_POPUP231AddPassword),
                    mszPassword, 0, 2, 8);
            cKeyboardPopup_setIncludeKey(mpKeyboard, 53, 0, 2);
            break;
        case 3:
            if (this->checkRoomName()) {
                mpParentState->onPopupEvent(this, 0xF);
            }
            break;
        }
        break;
    case cUIState::kONPREV:
        mpParentState->onPopupEvent(this, 20);
        break;
    case cUIState::kONCHANGE:
        if (obj == mpLBChannelName) {
            switch (cUIListBox_getCurrentEntryData(obj)) {
            case 0:
                cBXString_operatorE1((char*)&mszChannelName, cFEStateLobbyMenu_eliteChannelName);
                break;
            case 1:
                cBXString_operatorE1((char*)&mszChannelName, cFEStateLobbyMenu_advancedChannelName);
                break;
            case 2:
                cBXString_operatorE1((char*)&mszChannelName, cFEStateLobbyMenu_beginnerChannelName);
                break;
            case 3:
                cBXString_operatorE1((char*)&mszChannelName, cFEStateLobbyMenu_intermediateChannelName);
                break;
            }
        }
        break;
    case cUIState::kONKEYBOARDEND: {
        cKeyboardPopup* keyboard = mpKeyboard;
        switch (keyboard->miMiscData) {
        case 1:
            cBXString_operatorE1((char*)&mszRoomName, keyboard->mszEditString);
            cUIText_setAsciiString(mpTextRoomName, (const char*)mszRoomName);
            break;
        case 2:
            cBXString_operatorE1((char*)&mszPassword, keyboard->mszEditString);
            cUIText_setAsciiString(mpTextPassword, (const char*)mszPassword);
            break;
        }
    }
    default:
        cFEStateNet_onWidgetEvent((cFEStateNet*)this, pWidget, msg);
        break;
    }
}
