static inline void Measure1C2578(cUIText* text, const char* s, tRect* out)
{
    cFont* f = (cFont*)cUIText_getFont(text);
    cFont_textExtent(f, s, out, 0, f->Scale[0], f->Scale[1]);
}

/**
 * Sets a text widget's ascii string, shortening it with an ellipsis when it does not fit.
 *
 * Takes the widget's bounds from its virtual slot 20, scales its font's current size (font + 0x38/0x3C) by the widget's
 * scale (+0x50), copies @p str into an 80-byte buffer and, while the measured width (cFont_textExtent) exceeds the
 * available width minus the width of str_dot_dot_dot (the ellipsis), drops the last character. A shortened string gets
 * str_dot_dot_dot appended; an unshortened one is set unchanged (cUIText_setAsciiString). The buffer copy has no length
 * check.
 *
 * @param vtext  the cUIText to set
 * @param str  the text to show
 */
void cFEStateNetQuickMessages::setFittedText(cUIText* vtext, char* str)
{
    cUIText* text = (cUIText*)vtext;
    int cut = 0;
    t3Vector scale = *(&text->mScale);
    tRect box;
    ((cUIThing*)text)->getSize((t3Vector*)&box);
    cFont* font = (cFont*)cUIText_getFont(text);
    float sx = scale.x;
    float sy = scale.y;
    font->Scale[0] = font->BaseScale[0] * sx;
    font->Scale[1] = font->BaseScale[1] * sy;
    int i = strlen(str) - 1;
    char buf[80];
    strcpy(buf, str);
    const char* ell = str_dot_dot_dot;
    tRect sz;
    tRect dots;
    Measure1C2578(text, ell, &dots);
    Measure1C2578(text, buf, &sz);
    while (box.X - dots.W < sz.W) {
        cut = 1;
        buf[i--] = 0;
        Measure1C2578(text, buf, &sz);
    }
    if (cut) {
        strcat(buf, ell);
        cUIText_setAsciiString(text, buf);
    } else {
        cUIText_setAsciiString(text, str);
    }
}
