/**
 * Fills the help popup for the server-news screen (a cFEStateNet vtable's slot 25).
 *
 * Sets 3 help options (cFEStateNetHelpPopup_setNumHelpOptions__FPvi), the title "kT_HELP252ServerNews" (popup + 0x54), the description
 * "kT_HELP252ServerNewsMessage" and the options "kT_HELP252ScrollNews" (icon 3), "kT_HELPCmnPrevious" (1) and
 * "kT_BTNEAMessenger" (2) via cFEStateNetHelpPopup_setOption__FPviii.
 *
 * @param popup  the help popup to fill
 */
extern "C" void cFEStateNetNews_fillHelpPopup(cFEStateNet* self, cFEStateNetHelpPopup* popup)
{
    cFEStateNetHelpPopup_setNumHelpOptions(popup, 3);
    popup->muiScreenName = GetHashValue32(str_kT_HELP252ServerNews);
    cFEStateNetHelpPopup_setDescription(popup, 0, GetHashValue32(str_kT_HELP252ServerNewsMessage));
    cFEStateNetHelpPopup_setOption(popup, 0, GetHashValue32(str_kT_HELP252ScrollNews), 3);
    cFEStateNetHelpPopup_setOption(popup, 1, GetHashValue32(str_kT_HELPCmnPrevious), 1);
    cFEStateNetHelpPopup_setOption(popup, 2, GetHashValue32(str_kT_BTNEAMessenger), 2);
}
