//100%
INCLUDE_ASM("fe/feasyncfile", cPopupInfo_clear);
#ifdef SKIP_ASM
extern "C" void* memset(void* dst, int c, int n);


extern t3Vector t3vect_Zero;

/**
 * Resets a popup description to a plain message popup with no texts, options or confirmations.
 *
 * Zeroes the message, title, entry-box title and initial text, the five option names and confirmations and the
 * post-pending text (memset); sets mbPassUpdate 0, mbReceivePrev 1, mbCenterText 1, miMiscData 0, mbCenterOptions
 * 0, mfMinSize 0, meType 0 (no buttons), miLayerOffset 0, mvOffset zero, miDefaultOption -1, meBackgroundType 0
 * (online) and mbDeferEventsFlag 0. miMaxChars is left as it was.
 */
void cPopupInfo::clear()
{
    char* confirmEntry = (char*)&mtConfirmation;
    char* optionName = (char*)&mtOptionNames;
    memset((char*)&mtMessage, 0, 8);
    memset((char*)&mtTitle, 0, 8);
    memset((char*)&mtEntryBoxTitle, 0, 8);
    memset((char*)&mtEntryBoxInitial, 0, 8);
    int i;
    for (i = 4; i >= 0; i--) {
        memset(optionName, 0, 8);
        optionName += 8;
        memset(confirmEntry, 0, 0xC);
        confirmEntry += 0xC;
    }
    memset((char*)&mtPostPending, 0, 8);
    mbPassUpdate = 0;
    mbReceivePrev = 1;
    mbCenterText = 1;
    miMiscData = 0;
    mbCenterOptions = 0;
    mfMinSize = 0.0f;
    meType = 0;
    miLayerOffset = 0;
    mvOffset = t3vect_Zero;
    miDefaultOption = -1;
    meBackgroundType = 0;
    mbDeferEventsFlag = 0;
}
#endif

